<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>COVID-19 Emergency Response: From Detection to Recovery</title>
<style>
* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { background: #f0f4f8; font-family: 'Segoe UI', 'Helvetica Neue', Arial, sans-serif; }

.poster {
  width: 3508px;
  min-height: 4961px;
  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 30%, #f1f5f9 70%, #ffffff 100%);
  position: relative;
  overflow: hidden;
}

/* Subtle background pattern */
.poster::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background-image: radial-gradient(circle, #e2e8f0 1px, transparent 1px);
  background-size: 48px 48px;
  opacity: 0.5;
  pointer-events: none;
}

/* Decorative top bar */
.top-bar {
  height: 24px;
  background: linear-gradient(90deg, #005eb8 0%, #0077e6 50%, #005eb8 100%);
}

/* Header */
.header {
  text-align: center;
  padding: 80px 160px 60px;
  position: relative;
}
.badge {
  display: inline-block;
  background: linear-gradient(135deg, #005eb8 0%, #0077e6 100%);
  color: #fff;
  font-size: 32px;
  font-weight: 700;
  padding: 16px 48px;
  border-radius: 48px;
  letter-spacing: 2px;
  text-transform: uppercase;
  box-shadow: 0 8px 24px rgba(0,94,184,0.25);
  margin-bottom: 48px;
}
.header h1 {
  font-size: 120px;
  font-weight: 900;
  color: #0f172a;
  letter-spacing: -2px;
  line-height: 1.05;
  margin-bottom: 32px;
}
.header h1 span {
  color: #005eb8;
}
.subtitle {
  font-size: 48px;
  color: #475569;
  font-weight: 400;
  max-width: 2800px;
  margin: 0 auto;
  line-height: 1.4;
}

/* Hero Metrics */
.metrics-section {
  padding: 40px 160px 60px;
}
.metrics-row {
  display: flex;
  justify-content: center;
  gap: 48px;
  max-width: 3200px;
  margin: 0 auto;
}
.metric-card {
  background: #fff;
  border-radius: 32px;
  padding: 56px 48px;
  text-align: center;
  box-shadow: 0 16px 48px rgba(0,0,0,0.08);
  border: 3px solid #e2e8f0;
  flex: 1;
  transition: transform 0.2s;
  position: relative;
  overflow: hidden;
}
.metric-card::after {
  content: '';
  position: absolute;
  bottom: 0; left: 0; right: 0;
  height: 6px;
  background: #cbd5e1;
  border-radius: 0 0 28px 28px;
}
.metric-card.hero {
  border-color: #005eb8;
  background: linear-gradient(135deg, #005eb8 0%, #0077e6 100%);
  color: #fff;
  transform: scale(1.08);
  z-index: 2;
  box-shadow: 0 24px 64px rgba(0,94,184,0.3);
}
.metric-card.hero::after {
  background: rgba(255,255,255,0.3);
}
.metric-card.hero .metric-value {
  color: #fff;
  text-shadow: 0 4px 12px rgba(0,0,0,0.15);
}
.metric-card.hero .metric-label {
  color: rgba(255,255,255,0.92);
}
.metric-card.hero .metric-sublabel {
  color: rgba(255,255,255,0.75);
}
.metric-value {
  font-size: 96px;
  font-weight: 900;
  color: #005eb8;
  line-height: 1;
  letter-spacing: -2px;
}
.metric-label {
  font-size: 36px;
  font-weight: 700;
  color: #1e293b;
  margin-top: 20px;
  line-height: 1.3;
}
.metric-sublabel {
  font-size: 28px;
  color: #64748b;
  margin-top: 12px;
  font-weight: 500;
}

/* Section Title */
.section-title {
  text-align: center;
  padding: 60px 160px 40px;
}
.section-title h2 {
  font-size: 64px;
  font-weight: 800;
  color: #0f172a;
  display: inline-block;
  position: relative;
}
.section-title h2::after {
  content: '';
  display: block;
  width: 120px;
  height: 8px;
  background: linear-gradient(90deg, #005eb8, #f59e0b);
  border-radius: 4px;
  margin: 20px auto 0;
}
.section-title h2 span {
  color: #005eb8;
}
.section-title .section-desc {
  font-size: 36px;
  color: #64748b;
  margin-top: 24px;
  font-weight: 400;
}

/* Timeline Container */
.timeline-section {
  padding: 20px 160px 60px;
  display: flex;
  justify-content: center;
}
.timeline-wrapper {
  width: 3200px;
  height: 2200px;
  background: #fff;
  border-radius: 40px;
  box-shadow: 0 16px 48px rgba(0,0,0,0.06);
  border: 2px solid #e2e8f0;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  position: relative;
}
#timeline-container {
  width: 100%;
  height: 100%;
}
#timeline-container svg {
  width: 100% !important;
  height: auto !important;
  max-height: 100%;
}

/* Phase 4 Spotlight */
.spotlight {
  margin: 40px 160px 60px;
  background: linear-gradient(135deg, #fffbeb 0%, #fef3c7 50%, #fffbeb 100%);
  border: 4px solid #f59e0b;
  border-radius: 40px;
  padding: 64px 80px;
  box-shadow: 0 16px 48px rgba(245,158,11,0.15);
  position: relative;
}
.spotlight::before {
  content: '';
  position: absolute;
  top: -4px; left: 80px; right: 80px;
  height: 4px;
  background: linear-gradient(90deg, transparent, #f59e0b, transparent);
}
.spotlight-header {
  display: flex;
  align-items: center;
  gap: 28px;
  margin-bottom: 32px;
}
.spotlight-icon {
  width: 88px;
  height: 88px;
  background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%);
  border-radius: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 48px;
  font-weight: 900;
  box-shadow: 0 8px 24px rgba(245,158,11,0.3);
  flex-shrink: 0;
}
.spotlight-title {
  font-size: 52px;
  font-weight: 800;
  color: #92400e;
}
.spotlight-desc {
  font-size: 32px;
  color: #78350f;
  line-height: 1.6;
  margin-bottom: 40px;
  max-width: 2600px;
}
.spotlight-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
}
.spotlight-item {
  background: #fff;
  border-radius: 24px;
  padding: 36px 40px;
  font-size: 30px;
  color: #451a03;
  line-height: 1.5;
  box-shadow: 0 4px 16px rgba(0,0,0,0.04);
  border-left: 6px solid #f59e0b;
}
.spotlight-item strong {
  color: #b45309;
  font-size: 36px;
  display: block;
  margin-bottom: 12px;
}

/* Footer Metrics */
.footer-section {
  padding: 40px 160px 60px;
}
.footer-metrics {
  display: flex;
  justify-content: center;
  gap: 40px;
  max-width: 2800px;
  margin: 0 auto;
}
.fm-card {
  background: #fff;
  border-radius: 24px;
  padding: 40px 48px;
  text-align: center;
  box-shadow: 0 8px 32px rgba(0,0,0,0.06);
  border: 2px solid #e2e8f0;
  flex: 1;
}
.fm-value {
  font-size: 56px;
  font-weight: 900;
  color: #005eb8;
  line-height: 1;
}
.fm-label {
  font-size: 28px;
  color: #475569;
  margin-top: 16px;
  font-weight: 600;
}

/* Closing */
.closing {
  text-align: center;
  padding: 40px 240px 100px;
  font-size: 34px;
  color: #475569;
  line-height: 1.6;
  font-style: italic;
  position: relative;
}
.closing::before {
  content: '"';
  font-size: 120px;
  color: #cbd5e1;
  position: absolute;
  top: -20px;
  left: 180px;
  font-family: Georgia, serif;
  line-height: 1;
}

/* Bottom bar */
.bottom-bar {
  height: 16px;
  background: linear-gradient(90deg, #005eb8 0%, #f59e0b 50%, #005eb8 100%);
}
</style>
</head>
<body>
<div class="poster">
  <div class="top-bar"></div>

  <div class="header">
    <div class="badge">WHO-Guided Emergency Response</div>
    <h1>COVID-19 Emergency Response:<br><span>From Detection to Recovery</span></h1>
    <p class="subtitle">A structured, five-phase process backed by unprecedented global coordination across 194 WHO Member States and 6 WHO regions</p>
  </div>

  <div class="metrics-section">
    <div class="metrics-row">
      <div class="metric-card hero">
        <div class="metric-value">194</div>
        <div class="metric-label">WHO Member States<br>Coordinated</div>
        <div class="metric-sublabel">Across all 6 WHO regions worldwide</div>
      </div>
      <div class="metric-card hero">
        <div class="metric-value">~1.9 Billion</div>
        <div class="metric-label">COVAX Doses<br>Delivered</div>
        <div class="metric-sublabel">To 146 countries by mid-2023</div>
      </div>
      <div class="metric-card">
        <div class="metric-value">200+</div>
        <div class="metric-label">Technical Guidance<br>Documents</div>
        <div class="metric-sublabel">Covering every stage of response</div>
      </div>
    </div>
  </div>

  <div class="section-title">
    <h2>The Five-Phase <span>Response Flow</span></h2>
    <p class="section-desc">A systematic progression from surveillance through long-term recovery</p>
  </div>

  <div class="timeline-section">
    <div class="timeline-wrapper">
      <div id="timeline-container"></div>
    </div>
  </div>

  <div class="spotlight">
    <div class="spotlight-header">
      <div class="spotlight-icon">4</div>
      <div class="spotlight-title">Phase 4 Spotlight: Public Health & Social Measures</div>
    </div>
    <div class="spotlight-desc">
      Phase 4 represents the interventions most visible and personal to communities worldwide. These measures directly protected families, schools, and workplaces — making them the heart of the public experience.
    </div>
    <div class="spotlight-grid">
      <div class="spotlight-item">
        <strong>Testing & Contact Tracing</strong>
        Scaled PCR and rapid antigen testing deployed alongside digital and manual contact tracing systems to break transmission chains.
      </div>
      <div class="spotlight-item">
        <strong>Quarantine & Isolation</strong>
        Evidence-based duration guidelines continuously updated as new variants emerged, balancing public health with social impact.
      </div>
      <div class="spotlight-item">
        <strong>Vaccination (COVAX)</strong>
        Approximately 1.9 billion vaccine doses delivered to 146 countries by mid-2023, prioritizing health workers and vulnerable populations.
      </div>
      <div class="spotlight-item">
        <strong>Risk Communication</strong>
        Multilingual campaigns combating misinformation across social media, broadcast, and community outreach channels.
      </div>
    </div>
  </div>

  <div class="footer-section">
    <div class="footer-metrics">
      <div class="fm-card">
        <div class="fm-value">6</div>
        <div class="fm-label">WHO Regions Covered<br><span style="font-weight:400;color:#94a3b8;">Africa, Americas, SE Asia, Europe, E. Mediterranean, W. Pacific</span></div>
      </div>
      <div class="fm-card">
        <div class="fm-value">Millions</div>
        <div class="fm-label">Dashboard Data Points<br>Tracked Daily</div>
      </div>
      <div class="fm-card">
        <div class="fm-value">5 Jan 2020</div>
        <div class="fm-label">First Disease Outbreak<br>News Issued</div>
      </div>
      <div class="fm-card">
        <div class="fm-value">30 Jan 2020</div>
        <div class="fm-label">PHEIC Declaration<br>Date</div>
      </div>
    </div>
  </div>

  <div class="closing">
    This process-flow — from surveillance through recovery — represents a coordinated global health architecture designed to save lives and build resilience against future pandemics.
  </div>

  <div class="bottom-bar"></div>
</div>

<script src="/app/vendor/infographic.min.js"></script>
<script>
const infographic = new AntVInfographic.Infographic({
  container: '#timeline-container',
  width: '100%',
  height: '100%',
});
const dsl = `infographic sequence-timeline-rounded-rect-node
data
  title COVID-19 Emergency Response Flow
  desc From Detection to Recovery
  sequences
    - label Phase 1: Surveillance & Early Detection
      desc National labs report unusual illness via IHR. First alert issued 5 Jan 2020.
      icon eye
      value 194
    - label Phase 2: Risk Assessment & Alert
      desc Rapid risk assessments and situation reports. PHEIC declared 30 Jan 2020.
      icon alert triangle
      value 30
    - label Phase 3: Response Operations & Clinical Management
      desc Infection prevention, clinical protocols, workforce training, supply chain, and research.
      icon heart pulse
      value 200
    - label Phase 4: Public Health & Social Measures
      desc Testing, tracing, quarantine, COVAX vaccines, and risk communication campaigns.
      icon users
      value 1.9
    - label Phase 5: Recovery & Health System Resilience
      desc Restoring services, strengthening preparedness, addressing long COVID, and reviews.
      icon refresh cw
      value 6
theme
  palette #005eb8 #0891b2 #0d9488 #f59e0b #64748b`;
infographic.render(dsl);
document.fonts?.ready.then(() => {
  infographic.render(dsl);
}).catch((error) => console.error('Error waiting for fonts to load:', error));
</script>
</body>
</html>
HTMLEOF
